from _lib import File
F=File('pre2020_yamaha2t','o-y2t','Yamaha YZ125, YZ250 and YZ250X two-strokes 2010-2019: year-by-year changes on the long-running platform, dyno and weight, jetting, tester settings, known problems and fixes (knowledge push 2026-11)','Yamaha',['YZ125','YZ250','YZ250X'],list(range(2010,2020)))
R=F.R; M='magazine'
ALL=list(range(2010,2020))

# ---------------- YZ125
s=F.src(M,"Motocross Action - 2019 Yamaha YZ125 race test","https://motocrossactionmag.com/mxa-race-test-2019-yamaha-yz125-two-stroke","2018")
R('identity','YZ125 changes by year, 2006-2019',['YZ125'],ALL,"The 2010-2019 YZ125 is the 2005 engine and aluminium frame with the Kayaba SSS suspension it received for 2006. Changes since: 2011 a longer silencer with jetting to match (430 main, 6BFY43-3 needle), 2015 new bodywork, 2017 a 270 mm front disc with new pads (was 250 mm). Other years changed graphics only.",{'2011':'longer silencer, 430 main, 6BFY43-3 needle','2015':'new bodywork','2017':'270 mm front disc'},'OEM',s)
R('power_feel','YZ125 dyno and weight',['YZ125'],[2017,2018,2019],"On a magazine dyno the YZ125 peaked at 35.36 hp at 11,600 rpm and made 16.3 hp at 7,000 rpm. It picks up well from low to mid for a 125 and flattens on top, where the Austrian 125 of the same years pulls away; the rider has to work the clutch to keep it singing. It weighed 194 lb on a magazine scale in 2017 and listed at $6,499 in 2019.",{'peak_hp':35.36,'peak_rpm':11600,'hp_at_7000':16.3,'weight_lb':194,'msrp_usd_2019':6499},'MEASURED',s,'high')
R('setups','YZ125 tester settings',['YZ125'],[2015,2016,2017,2018,2019],"A magazine test crew's YZ125 setup, unchanged from test to test: fork stock 0.42 kg/mm springs, compression 12 clicks out, rebound 12 out, legs 5 mm up. Shock stock 4.7 kg/mm spring, 100 mm sag (Yamaha's figure is 105), high-speed compression 1-1/2 turns out, low-speed 12 clicks out, rebound 12 out. Faster or heavier riders need stiffer springs.",{'fork':'0.42 kg/mm, comp 12 out, reb 12 out, 5 mm up','shock':'4.7 kg/mm, sag 100 mm, HSC 1-1/2 turns, LSC 12 out, reb 12 out'},'TUNER',s)
R('setups','YZ125 jetting 2011-2019',['YZ125'],list(range(2011,2020)),"Jetting for the 2011-2019 YZ125 (38 mm Mikuni TMX): 430 main (a 440 and a 420 come with the bike), 40 pilot, 6BFY43-3 needle on the 3rd clip from the top, air screw 2-1/4 turns out. With porting or an aftermarket pipe go to the 440 main and add some race fuel to the mix for safety.",{'main':430,'pilot':40,'needle':'6BFY43-3, 3rd clip','air_screw':'2-1/4 turns','modified':'440 main'},'TUNER',s)
R('setups','YZ125 gearing',['YZ125'],ALL,"The YZ125 comes with a 48-tooth rear sprocket. Testers ran a 49 to sharpen second gear and reach third sooner.",{'stock_rear':48,'tested_rear':49},'TUNER',s)
R('engine_mods','YZ125 power steps',['YZ125'],ALL,"What testers found worked on the YZ125's flat top end: an aftermarket pipe (about 2 hp, with a matching silencer), an aftermarket reed cage, and cylinder and head porting, which may then need race fuel. A top end is cheap: an aftermarket piston is a little over $100.",{'pipe_gain_hp':'about 2'},'MEASURED',s)
s2=F.src(M,"Motocross Action - 2017 Yamaha YZ125 race test","https://motocrossactionmag.com/mxa-race-test-2017-yamaha-yz125","2016")
R('known_issues','YZ125 weak points',['YZ125'],ALL,"The YZ125 is close to trouble-free: clutch and engine durability are strengths. The complaints are the front brake on 2010-2016 bikes (the 270 mm disc from 2017 fixes it and can be fitted to earlier bikes), the stock front tyre on 2015-2019 bikes (testers swapped it), and a powerband that needs the clutch.",{},'TUNER',s2)
R('chassis','YZ125 handling',['YZ125'],ALL,"The YZ125 is under 200 lb, stable and forgiving, and its Kayaba SSS fork was rated the best stock fork of its time. It does not turn as sharply as the steel-frame Austrian 125s.",{},'TUNER',s2)

# ---------------- YZ250
s=F.src(M,"Motocross Action - 2019 Yamaha YZ250 race test","https://motocrossactionmag.com/mxa-race-test-2019-yamaha-yz250-two-stroke","2018")
Y=[2010,2011,2012,2013,2014,2015,2017,2018,2019]
R('identity','YZ250 platform',['YZ250'],Y,"The 2010-2019 YZ250 uses an engine that dates from 2003, the aluminium frame from 2005 and the Kayaba SSS suspension from 2006. Year changes were small: 2011 compression lowered from 10.9:1 to 10.6:1 (0.5 cc more head volume) to tolerate more fuels, 2015 new bodywork, 2017 a 270 mm front disc, 2018 blue rims.",{'2011':'compression 10.6:1 (was 10.9:1)','2015':'new bodywork','2017':'270 mm front disc'},'OEM',s)
R('power_feel','YZ250 dyno and weight',['YZ250'],Y,"On a magazine dyno the YZ250 made 46.08 hp at 8,800 rpm in 2019 and 47.10 hp in 2014. It weighed 218-219 lb. The power is broad and easier to manage than the Austrian 250 two-stroke of the same years, but it gives away drive off the start, uphill and in sand. Listed at $7,150 in 2014 and $7,399 in 2019.",{'peak_hp_2019':46.08,'peak_rpm_2019':8800,'peak_hp_2014':47.1,'weight_lb':'218-219'},'MEASURED',s,'high')
R('setups','YZ250 tester settings',['YZ250'],Y,"A magazine test crew's YZ250 setup: fork stock 0.43 kg/mm springs, 330 cc oil, compression 13 clicks out, rebound 14 out, legs 5 mm up (10 mm on the 2019 test). Shock stock 4.7 kg/mm spring (5.0 for fast or heavy riders), 100-105 mm sag, high-speed compression 1-3/4 turns out (stock 1-1/2), low-speed 8 clicks out (stock 13), rebound 8 out (stock 12).",{'fork':'0.43 kg/mm, 330 cc, comp 13 out, reb 14 out, 5-10 mm up','shock':'4.7 kg/mm, sag 100-105 mm, HSC 1-3/4 turns (stock 1-1/2), LSC 8 out (stock 13), reb 8 out (stock 12)'},'TUNER',s)
sj=F.src(M,"Motocross Action - guide to Yamaha YZ250 two-stroke jetting (1999-2021)","https://motocrossactionmag.com/mxa-guide-to-yamaha-yz250-two-stroke-jetting-1999-2021","2021")
R('setups','YZ250 jetting 2010-2019',['YZ250'],Y,"Jetting for the 2010-2019 YZ250 is the same every year: 178 main, 50 pilot, N3EW needle on the 2nd clip from the top, air screw 1 turn out (3/4 turn was preferred on 2010-2011 bikes, which also list a 50 power jet). The air screw is very sensitive between 1/2 and 1 turn. The stock setting is on the lean edge: with a pipe, porting or higher compression go to a 180 or 182 main, or blend race fuel into the pump fuel (one tester ratio: 1 gallon of race fuel to 5 of premix).",{'main':178,'pilot':50,'needle':'N3EW, 2nd clip','air_screw':'1 turn (3/4 on 2010-2011)','modified':'180 or 182 main'},'TUNER',sj)
R('setups','YZ250 gearing',['YZ250'],Y,"Testers add one tooth to the YZ250's rear sprocket (51 on the 2019 test) to cover the second-to-third shift.",{'tested_rear':51},'TUNER',s)
s4=F.src(M,"Motocross Action - 2014 Yamaha YZ250 test","https://motocrossactionmag.com/2014-test-ride-yamaha-yz250-two-stroke","2013")
R('engine_mods','YZ250 power and traction steps',['YZ250'],Y,"Tested changes on the YZ250: an aftermarket pipe is worth about 2 hp and, with a reed cage or porting, fills in the low-to-mid; a 9 oz flywheel weight improves traction and spreads the power; stiffer clutch springs (or a mix of stock and stiff) fix clutch feel. Anything that raises compression or flow needs richer jetting or better fuel, or it pings.",{'pipe_gain_hp':'about 2','flywheel_weight_oz':9},'MEASURED',s4)
R('known_issues','YZ250 weak points',['YZ250'],Y,"The YZ250 is nearly bug-free from the showroom. Complaints: it understeers and wiggles under power compared with the Austrian 250, the front brake is weak before the 2017 disc (a 260 or 270 mm disc fixes it), the stock front tyre on 2015-2019 bikes, and stock jetting that pings once the engine is modified.",{},'TUNER',s4)

# ---------------- YZ250X
s=F.src(M,"Motocross Action - 2019 Yamaha YZ250X test","https://motocrossactionmag.com/mxa-race-test-2019-yz250x-cross-country","2019")
X=[2016,2017,2018,2019]
R('identity','YZ250X against the YZ250',['YZ250X'],X,"The YZ250X arrived for 2016 as the off-road version of the YZ250. Engine: head volume 23.6 cc against 21.5 (compression 7.9:1 against 8.9:1), exhaust port 0.5 mm higher with a matching power valve, a softer power-valve governor, ignition timing pulled back from mid to high rpm and a narrower pipe. Gearbox: first and second the same, third lower, fourth taller and fifth much taller (like taking five teeth off a YZ250's rear sprocket). Chassis: same spring rates with softer valving, an 18 in rear wheel, a 22 mm rear axle (YZ250 25 mm), an O-ring chain, a side stand, a reserve tap at 0.5 gal and clutch springs 10% softer. The only change since has been the 270 mm front disc for 2017.",{'compression':'7.9:1','head_cc':23.6,'rear_wheel':'18 in','rear_axle_mm':22,'seat_height_in':38.2},'OEM',s)
R('setups','YZ250X tester settings',['YZ250X'],X,"A magazine test crew's YZ250X setup: fork 4.3 N/mm springs with 10 cc of oil added to each leg (it rode low and was harsh on chatter), compression 9 clicks out (stock 13), rebound 10 out. Shock 48 N/mm spring, 105 mm sag, high-speed compression 1-3/4 turns out (stock 1-1/2), low-speed 9 clicks out (stock 11), rebound 9 out (stock 11). It is too soft for pros or big jumps.",{'fork':'4.3 N/mm, +10 cc, comp 9 out (stock 13), reb 10 out','shock':'48 N/mm, sag 105 mm, HSC 1-3/4 turns, LSC 9 out (stock 11), reb 9 out (stock 11)'},'TUNER',s)
R('setups','YZ250X jetting and gearing',['YZ250X'],X,"YZ250X jetting used in testing: 178 main, 50 pilot, N3EW needle on the 2nd clip, air screw 1 turn (sensitive between 1/2 and 1). A modified engine wants a 180 main or better fuel. Stock gearing is 14/50; a 51 rear gives more drive into the tall fourth gear.",{'main':178,'pilot':50,'needle':'N3EW, 2nd clip','air_screw':'1 turn','gearing':'14/50 stock; 14/51 option'},'TUNER',s)
R('known_issues','YZ250X complaints',['YZ250X'],X,"Tester complaints on the YZ250X: fourth and fifth are too tall for tight trail, the tank is too small for a 40-mile loop (an oversize tank is the fix), the clutch springs are too soft, and converting to a 19 in rear wheel for motocross means lacing a 19 in rim to the stock hub with YZ250 spokes.",{},'TUNER',s)

if __name__=='__main__': F.write()
